pm.test("Devuelve 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("La respuesta es una lista", () => {
    pm.expect(pm.response.json()).to.be.an("array");
});

pm.test("Incluye los tres cursos iniciales", () => {
    const codigos = pm.response.json().map(curso => curso.codigo);

    pm.expect(codigos).to.include.members([
        "SIS-101",
        "SIS-205",
        "SIS-310"
    ]);
});

pm.test("Devuelve 201 Created", () => {
    pm.response.to.have.status(201);
});

pm.test("Incluye Location", () => {
    pm.expect(pm.response.headers.get("Location"))
        .to.be.a("string").and.not.empty;
});

if (pm.response.code === 201) {
    const curso = pm.response.json();

    pm.collectionVariables.set("cursoId", curso.id);

    pm.test("El curso tiene los datos esperados", () => {
        pm.expect(curso.codigo).to.eql("SIS-400");
        pm.expect(curso.cupos).to.eql(25);
        pm.expect(curso.activo).to.eql(true);
    });
}

pm.test("Devuelve 409 Conflict", () => {
    pm.response.to.have.status(409);
});

pm.test("Explica el conflicto", () => {
    const error = pm.response.json();

    pm.expect(error.status).to.eql(409);
    pm.expect(error.detail).to.include("SIS-400");
});

pm.test("Devuelve 400 Bad Request", () => {
    pm.response.to.have.status(400);
});

pm.test("Identifica los campos inválidos", () => {
    const error = pm.response.json();

    pm.expect(error.errores).to.have.property("nombre");
    pm.expect(error.errores).to.have.property("creditos");
});

pm.test("Devuelve 400", () => {
    pm.response.to.have.status(400);
});

pm.test("Identifica el código inválido", () => {
    pm.expect(pm.response.json().errores)
        .to.have.property("codigo");
});

pm.test("Devuelve 400 por JSON mal formado", () => {
    pm.response.to.have.status(400);
});

pm.test("Devuelve un error estructurado", () => {
    const error = pm.response.json();

    pm.expect(error.status).to.eql(400);
    pm.expect(error).to.have.property("detail");
});

pm.test("Devuelve 200 OK", () => {
    pm.response.to.have.status(200);
});

pm.test("Actualiza los cupos del curso correcto", () => {
    const curso = pm.response.json();

    pm.expect(curso.id).to.eql(
        Number(pm.collectionVariables.get("cursoId"))
    );
    pm.expect(curso.cupos).to.eql(30);
    pm.expect(curso.codigo).to.eql("SIS-400");
});

pm.test("Devuelve 404 Not Found", () => {
    pm.response.to.have.status(404);
});

pm.test("Identifica el curso inexistente", () => {
    const error = pm.response.json();

    pm.expect(error.status).to.eql(404);
    pm.expect(error.detail).to.include("Curso 99");
});

pm.test("Devuelve 400 por identificador inválido", () => {
    pm.response.to.have.status(400);
});

pm.test("El error indica estado 400", () => {
    pm.expect(pm.response.json().status).to.eql(400);
});

pm.test("Devuelve 204 No Content", () => {
    pm.response.to.have.status(204);
});

pm.test("La respuesta no tiene cuerpo", () => {
    pm.expect(pm.response.text()).to.eql("");
});

pm.test("Devuelve 404 al repetir la eliminación", () => {
    pm.response.to.have.status(404);
});

pm.test("Identifica el curso eliminado", () => {
    const error = pm.response.json();
    const id = pm.collectionVariables.get("cursoId");

    pm.expect(error.status).to.eql(404);
    pm.expect(error.detail).to.include("Curso " + id);
});

